// CSharpLexerInit initializes any static state used to implement CSharpLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewCSharpLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func CSharpLexerInit() {
	staticData := &CSharpLexerLexerStaticData
	staticData.once.Do(csharplexerLexerInit)
}

// NewCSharpLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewCSharpLexer(input antlr.CharStream) *CSharpLexer {
	CSharpLexerInit()
	l := new(CSharpLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &CSharpLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "CSharpLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

